package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class TrigHeightRelationsTest {
 private Rational distance(Question q){Matcher m=Pattern.compile("수평 거리가 (\\d+(?:\\.\\d+)?(?:/\\d+)?)m").matcher(q.prompt);assertTrue(m.find());assertTrue(q.prompt.contains("각이 45°"));assertTrue(q.prompt.contains("눈높이를 0m"));return Expression.number(m.group(1));}
 @Test public void publicDistanceAndEqualLegsGiveExactStepsAndMore100SmallProblems(){Generator g=new Generator(new Random(2080));Set<String> prompts=new HashSet<>(),answers=new HashSet<>();Set<Integer> positions=new HashSet<>();boolean decimal=false;for(int i=0;i<1000;i++){Question q=g.next("sec_trig_height",List.of(),i%2==0);Rational d=distance(q);assertTrue(d.compareTo(Rational.of(3))>=0&&d.compareTo(Rational.of(20))<=0);assertTrue(new Checker().check(q,List.of(),List.of(d.toString())).correct());assertFalse(new Checker().check(q,List.of(),List.of(d.add(Rational.ONE).toString())).correct());prompts.add(q.prompt);answers.add(d.toString());positions.add(q.correctChoice);decimal|=!d.isInteger();verify(q,d);}assertTrue(prompts.size()>100);assertTrue(answers.size()>100);assertTrue(positions.containsAll(Set.of(0,1,2,3)));assertTrue(decimal);}
 private void verify(Question q,Rational d){String signature=q.signature();StudyDiagram diagram=q.diagram;Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertSame(diagram,q.diagram);assertFalse(p.canTransfer());assertEquals(3,p.size());List<Rational> values=List.of(d,Rational.ONE,d);List<String> frames=List.of("수평 거리(m) = ","tan 45° = 높이 ÷ 밑변 = ","수평 거리 × tan 45° = ");for(int i=0;i<3;i++){assertEquals(frames.get(i),p.step(i).before);assertEquals("",p.step(i).after);assertTrue(p.step(i).accepts(values.get(i).toString()));assertTrue(p.step(i).accepts(values.get(i).decimalText()));assertFalse(p.step(i).accepts(values.get(i).add(Rational.ONE).toString()));}}
 @Test public void savedFractionsAndOldSameValueDraftRestoreByVersion(){Question q=new Question("sec_trig_height","어떤 지점에서 건물 꼭대기를 올려다본 각이 45°이고 건물 밑까지의 수평 거리가 7/3m입니다. 눈높이를 0m로 보면 건물 높이는?","","7/3");verify(q,distance(q));HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.stage=1;old.entries=new ArrayList<>(List.of("7/3"));p.restore(old,q.id);assertEquals(0,old.stage);assertEquals("",old.entries.get(0));assertEquals("trig-height-relations-v1",old.teachingVersion);old.entries.set(0,"7/3");old.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(old.copy(),q.id);assertEquals(1,restored.stage);assertEquals("7/3",restored.entries.get(0));}
}
